const AMMO_CAP = { arrows: [100, 200, 350, 450, 600, 750, 850, 1000, 1150, 1250, 1400, 1550, 1650, 1800, 1950, 2050], shuriken: [40, 80, 130, 190, 240, 290, 350, 400, 450, 510, 560, 610, 670, 720, 770, 830] };   // 표창도 1/3 (빌드 39)
