function itemCat(k) {
  const I = ITEMS[k]; if (!I) return 'mat';
  if (I.dish || I.food) return 'food';
  if (I.herb) return 'herb';
  if (I.potion || I.sup || I.heal || I.mana || I.use) return 'sup';
  if (I.book) return 'book';
  if (k.startsWith('rune_')) return 'rune';
  return 'mat';
}

