const PXM_W = {};
function pxMonSprite(id, fr) {
  if (typeof PXG !== 'undefined' && PXG[id]) return pxGiantSprite(id);
  const M = PXM[id]; if (!M) return null;
  const m = MONS[id], key = 'PM|' + id + '|' + (fr % 2);
  const hit = PXC.get(key + '|' + (FLASH || ''));
  if (hit) return hit;
  let rows = pxRows(fr % 2 && M.g2 ? M.g2 : M.g);
  if (fr % 2 && !M.g2) rows = [rows[0].replace(/./g, '.')].concat(rows.slice(0, -1)).map((r, i, a) => (i === a.length - 1 ? rows[rows.length - 1] : r));
  const W = Math.max(...rows.map(r => r.length)), H = rows.length, g = pxGrid(W + 2, H + 2);
  pxPut(g, rows, 1, 1);
  const body = pxRamp(m.body || m.cloth || '#8a8a8a'), dark = m.dark ? pxRamp(m.dark) : null;
  const pal = Object.assign({ C: body.b, c: dark ? dark.b : body.s, d: dark ? dark.s : body.d, Q: body.l, K: '#2a1e2a', k: '#2a1e2a', w: '#ffffff', e: '#2a1e2a', v: '#6a4428', S: m.skin || '#e0ac7e', s: m.skin ? pxRamp(m.skin).s : '#b08058' }, M.pal || {});
  return pxBake(key, g, pal, Math.round((W + 2) / 2), H + 1);
}

