PXU_WPN.pick = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], g = F.g != null ? F.g : 1, L = 4;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  const n = Math.ceil(Math.max(Math.abs(dx), Math.abs(dy)) * (L + g)); for (let j = 0; j <= n; j++) at(-g + (L + g) * j / n, 0, 'v');
  for (const [t, s, ch] of [[L + 0.3, 0, 'N'], [L + 0.4, -1, 'M'], [L + 0.4, 1, 'M'], [L + 0.1, -2, 'M'], [L - 0.5, -2.8, 'x'], [L + 0.1, 2, 'N'], [L - 0.3, 2.6, 'N']]) at(t, s, ch);
  return out; };
// 바위 주먹(골렘·거인): 손 자리에 돌덩이 (ms배로 크다)
PXU_WPN.rfist = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, r = k > 1.2 ? 1.6 : 1;
  const at = (t, s, ch) => out.push([hx + 0.5 + dx * t + px * s, hy + 0.5 + dy * t + py * s, ch]);
  for (let t = 0; t <= r + 0.6; t += 0.5) for (let s = -r; s <= r; s += 0.5) at(t + 0.6, s, s < -r / 2 ? 'Q' : t > r ? 'c' : 'C');
  return out; };
