/* ───────── 세계수 뿌리 · 세계수의 심장 몬스터 (빌드 58 시안 · 사용자 「전부 넣고」 — 네 모습 모두): 뿌리 거미 · 뿌리 웜 · 트렌트 수호자 · 드라이어드 · 이끼 골렘 · 우두머리 세계수의 뱀 · 두목 타락한 세계수의 심장 ─────────
   그림체는 빌드 55~57과 같은 「뭉툭」(큰 면 한 색 · 윗가장자리 빛 · 아래 그늘 · 부위마다 다른 글자로 PX_FX가 선을 긋는다).
   사람꼴(트렌트 수호자 · 이끼 골렘)은 g2 없이 엔진 숨쉬기(cr)로. 짐승(still)은 g2로 다리 · 몸 물결 · 심장 박동을, 떠 있는 드라이어드는 g2로 옷자락 · 머리칼을.
   광역기 땅속 독니(fang) · 가시 덩굴 채찍(lash)은 fmot.js. */
// 세계수 뿌리 몬스터 무기 (빌드 58): 트렌트 수호자 옹이 몽둥이 · 자작나무 지팡이 / 드라이어드 꽃 지팡이 · 씨앗 · 꽃가루 · 단풍잎
// 옹이 몽둥이 (트렌트 A 방패 나무 기사): 굵은 통나무 · 옹이 혹 · 끝이 굵다
PXU_WPN.wclub = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 5.6 * k;
  const at = (t, s, ch) => out.push([hx + dx * t + px * s, hy + dy * t + py * s, ch]);
  for (let t = -0.6; t <= L; t += 0.5) { const w = 0.5 + 0.9 * Math.max(0, t / L); for (let s = -w; s <= w + 0.01; s += 0.5) at(t, s, s < -w + 0.4 ? 'O' : 'v'); }
  for (const [t, s] of [[L * 0.45, 1.4], [L * 0.75, -1.6], [L * 0.9, 1.5]]) at(t, s, 'v');
  return out; };
PXU_FXW.wclub = 'club';
// 자작나무 지팡이 (트렌트 C 꽃 피운 수호자): 흰 자작 자루에 검은 눈 · 끝에 분홍 꽃송이
PXU_WPN.bstaff = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], k = (d && d.ms) || 1, L = 7 * k;
  const at = (t, s, ch) => out.push([hx + dx * t + px * s, hy + dy * t + py * s, ch]);
  for (let t = -2; t <= L; t += 0.5) at(t, 0, Math.round(t * 2) % 5 === 0 ? 'k' : 'U');
  for (const [t, s, ch] of [[L + 0.6, 0, 'R'], [L + 1.1, -0.8, 'r'], [L + 1.1, 0.8, 'R'], [L + 1.6, 0, 'w'], [L + 0.4, 1.2, 'G'], [L + 0.2, -1.2, 'G']]) at(t, s, ch);
  return out; };
PXU_FXW.bstaff = 'staff';
// 꽃 지팡이 (드라이어드 A): 가는 초록 줄기 · 잎 둘 · 끝에 활짝 핀 분홍 꽃
PXU_WPN.fbloom = (F, d) => { const [hx, hy] = pxsMHand(F), [dx, dy] = pxsDir(F.a || 0), px = -dy, py = dx, out = [], L = 4.6;
  const at = (t, s, ch) => out.push([hx + dx * t + px * s, hy + dy * t + py * s, ch]);
  for (let t = -0.6; t <= L; t += 0.5) at(t, 0, 'g');
  at(L * 0.5, 0.9, 'G'); at(L * 0.65, -0.9, 'G');
  for (const [t, s, ch] of [[L + 0.6, 0, 'Y'], [L + 0.6, -1, 'R'], [L + 0.6, 1, 'R'], [L + 1.4, 0, 'R'], [L - 0.2, 0, 'R'], [L + 1.2, -0.9, 'r'], [L + 1.2, 0.9, 'r']]) at(t, s, ch);
  return out; };
PXU_FXW.fbloom = 'dagger';
// 씨앗 구슬 (드라이어드 B): 손바닥 위에 떠 있는 빛나는 초록 씨앗
PXU_WPN.fseed = (F, d) => { const [hx, hy] = pxsMHand(F), out = [];
  for (const [x, y, ch] of [[0, -2, 'y'], [1, -2, 'y'], [0, -3, 'Y'], [1, -3, 'y'], [0, -4, 'y'], [-1, -3, 'G'], [2, -2.6, 'G'], [0.5, -4.8, 'G']]) out.push([hx + x, hy + y, ch]);
  return out; };
PXU_FXW.fseed = 'dagger';
// 꽃가루 구슬 (드라이어드 C): 손 위의 노란 꽃가루 뭉치와 흩날리는 점
PXU_WPN.fpollen = (F, d) => { const [hx, hy] = pxsMHand(F), out = [];
  for (let y = -4; y <= -1; y++) for (let x = -1; x <= 2; x++) { const r = Math.hypot(x - 0.5, y + 2.5); if (r <= 1.8) out.push([hx + x, hy + y, r < 0.8 ? 'X' : 'Y']); }
  out.push([hx - 1.6, hy - 4.6, 'Y'], [hx + 2.6, hy - 5, 'Y'], [hx + 0.6, hy - 5.8, 'X']);
  return out; };
PXU_FXW.fpollen = 'dagger';
// 단풍잎 (드라이어드 D): 손바닥 위에 떠 있는 빛나는 붉은 단풍잎
PXU_WPN.fmaple = (F, d) => { const [hx, hy] = pxsMHand(F), out = [];
  for (const [x, y, ch] of [[0, -2, 'R'], [0, -3, 'O'], [0, -4, 'R'], [-1, -3, 'R'], [1, -3, 'R'], [-2, -3.6, 'O'], [2, -3.6, 'O'], [-1, -4.6, 'O'], [1, -4.6, 'O'], [0, -5.4, 'Y'], [0, -1.2, 'r']]) out.push([hx + x, hy + y, ch]);
  return out; };
PXU_FXW.fmaple = 'dagger';
