  [[-0.24, -0.26, 0.34, 0.24], [-0.56, 0.04, 0.18, 0.14], [0.2, -0.5, 0.2, 0.14]].forEach(([dx, dy, rx, ry]) => P.ell(x + dx * s, cy + dy * s, rx * s, ry * s, l2));
