    const r = fieldRng(2); for (let i = 0; i < 40; i++) { const X = (r() < 0.5 ? -1 : 1) * r() * 0.8, z = 1.2 + r() * 6, [x, y] = ap(X, 0, z); P.ell(x, y, 120 / z * 0.06, 120 / z * 0.03, Pix.c(i % 2 ? '#7a8a6a' : '#6a7a5a')); }
