      const t1 = ap(s * 1.7, Hc, 1), t2 = ap(s * 1.7, Hc, 8), t3 = ap(s * 2.3, Hc + 0.05, 8), t4 = ap(s * 2.6, Hc + 0.05, 1);
      P.poly([t1, t2, t3, t4, [e, t4[1]], [e, t1[1]]], Pix.c('#d89a6a'));
      P.poly([t1, t2, [t2[0], t2[1] + 2], [t1[0], t1[1] + 3]], Pix.c('#e8b488'));
