  for (let x = 4; x < 480; x += 9) R(g, x, 8, 4, 7, '#5e4630'); R(g, 0, 9, 480, 1, '#8a8a90'); R(g, 0, 14, 480, 1, '#8a8a90');
  const [fore, fo] = mkCanvas(480, 28);
