  for (let x = 0; x < 480; x += 5) { const h = 3 + Math.floor(r() * 4); R(m, x, 101 - h, 1, h, '#9ab86a'); R(m, x + 1, 101 - h + 1, 1, h - 1, '#7a9a5a'); }
  const [gr, g] = mkCanvas(480, 28);
