  const T = MAST_TIERS[t];
  if (!S.bld.training) return '훈련소가 필요해요';
  if (a.lv < T.lv) return `${T.name}은 Lv${T.lv}부터`;
  if (jobTier(a.cls) < T.job) return `${T.name}은 ${T.job}차 전직 뒤에`;
  if (a.status !== 'idle') return '상단에 있을 때만';
