  const miss = licReqs(a).find(r => !r.ok);
  if (miss) return `${miss.label} ${miss.need} 이상이어야 해요. (지금 ${miss.cur})`;
  if (S.gold < L.fee) return '심사비가 모자라요.';
  S.gold -= L.fee;
  a.rank = (a.rank || 0) + 1;
