  log(v.earned ? `${D.name} 상단이 ${g$(v.earned)}어치를 사서 돌아갔다.` : `${D.name} 상단이 빈손으로 돌아갔다.`, v.earned ? 'good' : '');
  if (!v.earned) S.king.favor[v.k] = Math.max(0, favorOf(v.k) - 3);
