const q3LvY = (yb, k) => yb - Q3S.leg - k * Q3S.lv;   // k단 받침 윗면 (아래부터 0)
// 칸 i의 자리: 12칸까지는 단마다 진열대 하나에 한 칸(물건 둘), 그보다 많으면 단마다 진열대 하나에 두 칸(물건 하나씩)
