    if (nt > 0.2) q3Light(g, K, T, { amb: 0, ambN: 0.35, tint: '#0a0c1c', lamps: [[gx + 23, gy + 34, 40], [33, FB - 108, 24], [100, FB - 10, 30]], wins: [] }, t);
    for (const [x, y] of [[33, FB - 108], [gx + 23, gy + 4]]) { qF(g, x - 3, y - 4, 7, 7, '#2a2230'); qF(g, x - 2, y - 3, 5, 5, '#f8c060'); }
