    q3Beam(g, K.top + 2, W, '#4e3018');
    q3Floor(g, K, '#9a7a48', '#8e6e40', '#6a522c', 10);
    const r = rng(29); for (let k = 0; k < 160; k++) qF(g, Math.floor(r() * W), FB + 3 + Math.floor(r() * (K.H - FB - 3)), 2, 1, r() < 0.5 ? '#d8b050' : '#b08a30');
