    for (const y of [FB - 18, FB - 10]) { qF(g, 0, y, W, 3, '#8a5a30'); qF(g, 0, y, W, 1, '#b08048'); }
    qB(g, aHay(26, 12), 6, FB - 1); qB(g, aHay(20, 10), 10, FB - 12);
    qB(g, aTrough(30), 116, FB + 2);
