    for (const [rx, ry, c] of [[44, 12, '#7ad8f0'], [38, 10, '#b88aff'], [26, 7, '#7ad8f0']]) for (let a = 0; a < 360; a += 3) { const r = a * Math.PI / 180; qP(g, cx + Math.cos(r) * rx, cy + Math.sin(r) * ry, c); }
