    if (f.nest) post.push(g => { const yy = y - eH(f) * z / ZE - 5; R(g, x - 3, yy, 7, 2, '#a8743e'); R(g, x - 2, yy - 1, 5, 1, '#d8b878'); R(g, x - 1, yy - 2, 1, 1, '#f0e8d8'); R(g, x + 1, yy - 2, 1, 1, '#f0e8d8'); });
    if (!fighting) return;
