      if ((a.fat || 0) >= 60) R(g, x0 + 12.5, y0 + 3, 1.5, 1.5, a.fat >= 85 ? '#e0503f' : '#f0b43c');
      staDots(g, e.sta && e.sta[a.id], x0 - 11, y0);
