  pxPut(gr, pxRows(`
...vv...
..vKKv..
..KYYK..
..KYYK..
..KyyK..
..vKKv..
...vv...
...v....
...v....
...v....
..vvv...
`), 0, 0);
  const f = Math.floor(t * 6) % 2;
