// 모험가 창 탭: 기본 직업 계열(2·3차 전직도 계열을 따른다) + 선술집 손님(고용 후보)
const ADV_CATS = [['warrior', '전사'], ['archer', '궁수'], ['mage', '마법사'], ['cleric', '성직자'], ['rogue', '도적'], ['porter', '짐꾼'], ['guest', '선술집']];
const advCatOf = a => jobBase(a.cls);
