    const s = pxsAdvSprite(a, 'idle', 0), Z2 = 3, x = 40 + i * 104, yy = y + 40 + 120;
    g.drawImage(s.cv, Math.round(x + 40 - s.ax * Z2), Math.round(yy - s.ay * Z2), s.cv.width * Z2, s.cv.height * Z2);
